using System;
using System.Threading;
using NAudio.CoreAudioApi;
using NAudio.Wave;
using NAudio.Wave.SampleProviders;
namespace DualSpeaker {
 public class LeftOnly:ISampleProvider {long f;public WaveFormat WaveFormat{get{return WaveFormat.CreateIeeeFloatWaveFormat(48000,2);}}public int Read(float[] b,int o,int c){for(int i=0;i<c/2;i++){b[o+2*i]=(float)(.05*Math.Sin(2*Math.PI*1100*f/48000));b[o+2*i+1]=0;f++;}return c;}}
 public static class SignalChecks {
  public static void MasterSelfTest(){var ring=new AudioRing(48000);var data=new float[96000];for(int i=0;i<data.Length;i++)data[i]=.25f;ring.Write(data,48000);var settings=new Settings{LeftGain=.8f,RightGain=.4f,MasterGain=1};
   foreach(float volume in new[]{0f,.5f,1f}){settings.MasterGain=volume;var left=new OutputProvider(ring,44100,true,settings);var right=new OutputProvider(ring,44100,false,settings);float[] l=new float[200],r=new float[200];left.Read(l,0,l.Length);right.Read(r,0,r.Length);for(int i=0;i<l.Length;i++)if(Math.Abs(l[i]-.2f*volume)>.00001||Math.Abs(r[i]-.1f*volume)>.00001)throw new Exception("总音量未按比例作用于双音响。");}
   settings.MasterGain=.5f;settings.MasterMuted=true;var output=new OutputProvider(ring,44100,true,settings);float[] b=new float[200];output.Read(b,0,b.Length);foreach(float v in b)if(v!=0)throw new Exception("总静音未生效。");settings.MasterMuted=false;output.Read(b,0,b.Length);foreach(float v in b)if(Math.Abs(v-.1f)>.00001)throw new Exception("取消静音后音量未保留。");Files.Log("MASTER SELFTEST PASS | 0/50/100%, left/right balance preserved, mute/unmute retains level");
   var keys=new Settings{MasterGain=.48f,VolumeStepPercent=8};if(MediaVolumeKeys.AdjustVolume(keys,0xAF)!=56||MediaVolumeKeys.AdjustVolume(keys,0xAE)!=48)throw new Exception("旋钮灵敏度步长错误。");MediaVolumeKeys.AdjustVolume(keys,0xAD);if(!keys.MasterMuted||Math.Abs(keys.MasterGain-.48f)>.00001)throw new Exception("旋钮按下未保留音量并静音。");MediaVolumeKeys.AdjustVolume(keys,0xAD);if(keys.MasterMuted)throw new Exception("旋钮再次按下未取消静音。");keys.MasterGain=0;for(int i=0;i<13;i++)MediaVolumeKeys.AdjustVolume(keys,0xAF);if(keys.MasterGain!=1)throw new Exception("旋钮调高未达到上限。");for(int i=0;i<13;i++)MediaVolumeKeys.AdjustVolume(keys,0xAE);if(keys.MasterGain!=0)throw new Exception("旋钮调低未达到下限。");keys.VolumeStepPercent=3;if(MediaVolumeKeys.AdjustVolume(keys,0xAF)!=3)throw new Exception("自定义旋钮步长无效。");Files.Log("KNOB SELFTEST PASS | 8% step, custom step, limits, push-to-mute");
  }
  public static void Regression(){var settings=Devices.Initial();settings.BufferMs=120;settings.OutputBufferMs=60;string beforeConsole=Devices.Default(Role.Console),beforeMedia=Devices.Default(Role.Multimedia);float beforeVolume;bool beforeMute;using(var endpoint=Devices.Open(settings.BusId)){beforeVolume=endpoint.AudioEndpointVolume.MasterVolumeLevelScalar;beforeMute=endpoint.AudioEndpointVolume.Mute;}
   long missingLeft,missingRight;int corrections;
   using(var engine=new AudioEngine(settings)){engine.Start(true);using(var endpoint=Devices.Open(settings.BusId)){for(int i=0;i<3;i++){endpoint.AudioEndpointVolume.Mute=false;endpoint.AudioEndpointVolume.MasterVolumeLevelScalar=0;Thread.Sleep(250);if(!endpoint.AudioEndpointVolume.Mute)throw new Exception("静音保护未拦截解除静音。");endpoint.AudioEndpointVolume.MasterVolumeLevelScalar=.12f;Thread.Sleep(250);if(!endpoint.AudioEndpointVolume.Mute||endpoint.AudioEndpointVolume.MasterVolumeLevelScalar>.0001)throw new Exception("静音保护未拦截音量调整。");}}
    engine.BeginDemo();Thread.Sleep(10000);engine.EndDemo();missingLeft=engine.Left.MissingFrames;missingRight=engine.Right.MissingFrames;corrections=engine.MuteCorrections;Files.Log("LOW_LATENCY | missing="+missingLeft+","+missingRight+" | lag="+engine.Left.LagMs+","+engine.Right.LagMs+" | corrections="+corrections);engine.Stop();}
   using(var endpoint=Devices.Open(settings.BusId)){if(Math.Abs(endpoint.AudioEndpointVolume.MasterVolumeLevelScalar-beforeVolume)>.001||endpoint.AudioEndpointVolume.Mute!=beforeMute)throw new Exception("退出后音量或静音状态未恢复。");}
   if(Devices.Default(Role.Console)!=beforeConsole||Devices.Default(Role.Multimedia)!=beforeMedia)throw new Exception("退出后默认设备未恢复。");if(missingLeft!=0||missingRight!=0)throw new Exception("低缓冲测试发生缺帧。");Files.Save(System.IO.Path.Combine(Files.Root,"mute-regression-test.json"),new{Time=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),Pass=true,MuteCorrections=corrections,SourceBufferMs=120,OutputBufferMs=60,LeftMissing=missingLeft,RightMissing=missingRight,RestoreVerified=true});Files.Log("REGRESSION PASS | mute guard, low buffer, audio setting restore");
  }
  public static void ProcessProbe(){using(var capture=new ProcessAudioCapture()){long frames=0;float peak=0;double l=0,r=0;capture.DataAvailable+=(s,e)=>{frames+=e.BytesRecorded/4;var a=AudioConvert.Decode(e.Buffer,e.BytesRecorded,capture.WaveFormat,false);for(int i=0;i<a.Length;i+=2){l+=a[i]*a[i];r+=a[i+1]*a[i+1];peak=Math.Max(peak,Math.Abs(a[i]));}};capture.StartRecording();Thread.Sleep(2500);capture.StopRecording();Files.Log("PROCESS_CAPTURE | frames="+frames+" | peak="+peak+" | packets="+capture.Packets+" | L_RMS="+Math.Sqrt(l/frames)+" | R_RMS="+Math.Sqrt(r/frames));}}
  public static void Source(bool demo){using(var d=Devices.Open(Devices.Initial().BusId)){float volume=d.AudioEndpointVolume.MasterVolumeLevelScalar;bool mute=d.AudioEndpointVolume.Mute;try{d.AudioEndpointVolume.Mute=true;d.AudioEndpointVolume.MasterVolumeLevelScalar=0;using(var o=new WasapiOut(d,AudioClientShareMode.Shared,false,60)){o.Init(new SampleToWaveProvider(demo?(ISampleProvider)new DemoMusic():new LeftOnly()));o.Play();Thread.Sleep(demo?8500:4000);o.Stop();}}finally{d.AudioEndpointVolume.MasterVolumeLevelScalar=volume;d.AudioEndpointVolume.Mute=mute;}}}
  public static void FxProbe(){using(var d=Devices.Open(Devices.Initial().BusId)){var field=typeof(MMDevice).GetField("deviceInterface",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);object com=field.GetValue(d);var method=field.FieldType.GetMethod("OpenPropertyStore");var access=Enum.ToObject(method.GetParameters()[0].ParameterType,2);object[] args={access,null};int hr=(int)method.Invoke(com,args);Files.Log("FX_STORE | result=0x"+hr.ToString("X8"));if(hr<0)return;object store=args[1];var type=typeof(MMDevice).Assembly.GetType("NAudio.CoreAudioApi.Interfaces.IPropertyStore");var key=new PropertyKey(new Guid("1da5d803-d492-4edd-8c23-e0c0ffee7f0e"),5);object[] get={key,new NAudio.CoreAudioApi.Interfaces.PropVariant()};int result=(int)type.GetMethod("GetValue").Invoke(store,get);var original=(NAudio.CoreAudioApi.Interfaces.PropVariant)get[1];Files.Log("FX_VALUE | result=0x"+result.ToString("X8")+" | vt="+original.vt+" | value="+original.uintVal);System.Runtime.InteropServices.Marshal.ReleaseComObject(store);}}
  public static void Matrix(){var s=Devices.Initial();using(var d=Devices.Open(s.BusId)){float volume=d.AudioEndpointVolume.MasterVolumeLevelScalar;bool mute=d.AudioEndpointVolume.Mute;try{d.AudioEndpointVolume.Mute=true;d.AudioEndpointVolume.MasterVolumeLevelScalar=0;using(var cap=new WasapiLoopbackCapture(d))using(var o=new WasapiOut(d,AudioClientShareMode.Shared,false,80)){double l=0,r=0,cross=0;long n=0;cap.DataAvailable+=(sender,e)=>{var a=AudioConvert.Decode(e.Buffer,e.BytesRecorded,cap.WaveFormat,false);for(int i=0;i<a.Length;i+=2){l+=a[i]*a[i];r+=a[i+1]*a[i+1];cross+=a[i]*a[i+1];n++;}};cap.StartRecording();o.Init(new SampleToWaveProvider(new LeftOnly()));o.Play();Thread.Sleep(2200);o.Stop();cap.StopRecording();Thread.Sleep(150);Files.Log("MATRIX | leftRMS="+Math.Sqrt(l/n)+" | rightRMS="+Math.Sqrt(r/n)+" | leakage="+Math.Sqrt(r/Math.Max(l,1e-20))+" | correlation="+cross/Math.Sqrt(Math.Max(l*r,1e-20)));}}finally{d.AudioEndpointVolume.MasterVolumeLevelScalar=volume;d.AudioEndpointVolume.Mute=mute;}}}
 }
}
